from collections import deque
def solve(g):
    H,W=len(g),len(g[0])
    bg=max(set(x for row in g for x in row), key=lambda v:sum(row.count(v) for row in g))
    # shape color: the other non-bg colors forming outline
    colors=set(x for row in g for x in row)-{bg}
    shape=[c for c in colors if c!=0 and sum(row.count(c) for row in g)>1]
    # determine which color is the frame outline: pick color whose cells form hollow rect
    shape=shape[0] if shape else None
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==shape]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    g2=[row[:] for row in g]
    # interior: flood bg from border avoiding shape cells
    dq=deque()
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in (0,W-1):
            if g[r][c]!=shape and not seen[r][c]: seen[r][c]=True; dq.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if g[r][c]!=shape and not seen[r][c]: seen[r][c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]!=shape:
                seen[nr][nc]=True; dq.append((nr,nc))
    # interior cells = not seen and not shape
    interior=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=shape and not seen[r][c]]
    # gap: find wall openings. Wall cells of shape on border of bbox:
    # check each side: top row r0 within c0..c1: cells that are bg instead of shape -> gap
    gaps=[]
    for side,(rr,cc,dirs) in [('top',(r0,c0,[(0,1)])),('bottom',(r1,c0,[(0,-1)])),('left',(c0,r0,[(1,0)])),('right',(c1,r0,[(0,1)]) )]:
        pass
    # simpler: scan perimeter rows/cols of bbox
    for c in range(c0,c1+1):
        if g[r0][c]!=shape: gaps.append(('top',r0,c))
        if g[r1][c]!=shape: gaps.append(('bottom',r1,c))
    for r in range(r0,r1+1):
        if g[r][c0]!=shape: gaps.append(('left',r,c0))
        if g[r][c1]!=shape: gaps.append(('right',r,c1))
    return shape,(r0,r1,c0,c1),gaps,interior
