from collections import Counter

def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    rem=[c for c in cnt if c!=bg]
    outline=max(rem,key=lambda c:cnt[c])
    out=[row[:] for row in g]
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==outline]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if g[r][c]!=outline: out[r][c]=4
    # gaps on bbox perimeter, grouped along the wall
    runs=[]; side_list=None
    def collect(side,fix,idx,varrange):
        pts=[(varrange[idx],idx) for idx in varrange if g[fix][idx]!=outline]
        return pts
    top=collect('top',r0,None,list(range(c0,c1+1)))
    bot=collect('bottom',r1,None,list(range(c0,c1+1)))
    lf=collect('left',None,c0,list(range(r0,r1+1)))
